#!/usr/bin/env node
/**
 * Sync canonical runner labels from runners.yaml into:
 *   - .github/actions/runner-names/action.yml (action outputs)
 *   - .github/workflows/*.{yml,yaml} (env block + literal replacements)
 *
 * Usage: node .github/scripts/sync-runner-names.mjs
 */

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const repoRoot = path.resolve(__dirname, '../..')
const runnersYamlPath = path.join(repoRoot, '.github/actions/runner-names/runners.yaml')
const actionPath = path.join(repoRoot, '.github/actions/runner-names/action.yml')
const workflowsDir = path.join(repoRoot, '.github/workflows')

const ENV_MARKER = '# Canonical runner labels — .github/actions/runner-names/runners.yaml'

function parseRunnersYaml (text) {
  const runners = {}
  for (const line of text.split('\n')) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    const colon = trimmed.indexOf(':')
    if (colon === -1) continue
    const key = trimmed.slice(0, colon).trim()
    const value = trimmed.slice(colon + 1).trim()
    if (key && value) runners[key] = value
  }
  return runners
}

function envName (key) {
  return 'RN_' + key.toUpperCase()
}

function envExpr (key) {
  return '${{ env.' + envName(key) + ' }}'
}

function describeKey (key, value) {
  const labels = {
    orch: 'Default orchestration runner',
    u22: 'GitHub-hosted Ubuntu 22.04',
    u24: 'GitHub-hosted Ubuntu 24.04',
    u22_arm: 'GitHub-hosted Ubuntu 22.04 ARM64',
    u24_arm: 'GitHub-hosted Ubuntu 24.04 ARM64',
    mac14: 'GitHub-hosted macOS 14',
    mac14_xl: 'GitHub-hosted macOS 14 xlarge',
    mac15: 'GitHub-hosted macOS 15',
    mac15_intel: 'GitHub-hosted macOS 15 Intel',
    mac15_lg: 'GitHub-hosted macOS 15 large',
    mac15_xl: 'GitHub-hosted macOS 15 xlarge',
    win22: 'GitHub-hosted Windows Server 2022',
    win25: 'GitHub-hosted Windows Server 2025',
    qvac_u22: 'Self-hosted QVAC Ubuntu 22.04 x64',
    qvac_u22_gpu: 'Self-hosted QVAC Ubuntu 22.04 x64 GPU',
    qvac_u24: 'Self-hosted QVAC Ubuntu 24.04 x64',
    qvac_u24_gpu: 'Self-hosted QVAC Ubuntu 24.04 x64 GPU',
    qvac_win25: 'Self-hosted QVAC Windows 2025 x64',
    qvac_win25_gpu: 'Self-hosted QVAC Windows 2025 x64 GPU',
    ai_linux: 'Self-hosted AI run Linux',
    ai_linux_gpu: 'Self-hosted AI run Linux GPU',
    ai_u22: 'Self-hosted AI run Ubuntu 22.04',
    ai_win11_gpu: 'Self-hosted AI run Windows 11 GPU',
    gen_win11: 'Self-hosted Windows 11 image builder',
    mini_m4: 'Self-hosted Mac mini M4',
    mini_m4_gpu: 'Self-hosted Mac mini M4 GPU'
  }
  if (key.startsWith('lbl_')) {
    return `Benchmark device label (${value})`
  }
  return labels[key] || value
}

function writeActionYml (runners) {
  const outputLines = Object.entries(runners).map(([key, value]) => {
    const desc = describeKey(key, value).replace(/"/g, '\\"')
    return `  ${key}:\n    description: "${desc}"\n    value: ${value}`
  })

  const envExportLines = Object.entries(runners).map(([key, value]) => {
    return `        echo "${envName(key)}=${value}" >> "$GITHUB_ENV"`
  })

  const content = `name: Runner names
description: >-
  Canonical GitHub Actions runner labels for QVAC CI. Values are defined in
  runners.yaml. Workflow jobs use env.RN_* (generated by sync-runner-names.mjs);
  steps may reference outputs directly (steps.runner_names.outputs.<key>).

outputs:
${outputLines.join('\n')}

runs:
  using: composite
  steps:
    - name: Export runner env
      shell: bash
      run: |
        set -euo pipefail
${envExportLines.join('\n')}
`

  fs.writeFileSync(actionPath, content.endsWith('\n') ? content : content + '\n')
}

function runnerEnvLines (runners) {
  return Object.entries(runners).map(([key, value]) => {
    return `  ${envName(key)}: ${value}`
  })
}

function buildEnvBlock (runners) {
  return [ENV_MARKER, 'env:', ...runnerEnvLines(runners)].join('\n')
}

function runnerEnvInsertLines (runners) {
  return [ENV_MARKER, ...runnerEnvLines(runners)]
}

function removeExistingRunnerEnv (lines) {
  const next = lines.slice()
  while (true) {
    const markerIndex = next.findIndex((line) => line.trim() === ENV_MARKER)
    if (markerIndex === -1) break

    let end = markerIndex + 1
    while (end < next.length && /^  RN_/.test(next[end])) {
      end += 1
    }
    next.splice(markerIndex, end - markerIndex)
  }

  for (let i = 0; i < next.length; i++) {
    if (next[i] !== 'env:') continue
    let end = i + 1
    while (end < next.length && /^  RN_/.test(next[end])) {
      end += 1
    }
    if (end > i + 1) {
      next.splice(i, end - i)
      if (next[i]?.trim() === '' && next[i - 1]?.trim() === '') {
        next.splice(i, 1)
      }
    }
  }

  return next
}

function findWorkflowLevelEnv (lines) {
  for (let i = 0; i < lines.length; i++) {
    if (lines[i] !== 'env:') continue
    let end = i + 1
    while (end < lines.length && /^  [A-Za-z0-9_]+:/.test(lines[end])) {
      end += 1
    }
    return { start: i, end, insertAt: i + 1 }
  }
  return null
}

function insertEnvBlock (lines, runners) {
  let insertAt = 0
  let inOn = false
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (/^on:\s*$/.test(line)) {
      inOn = true
      insertAt = i + 1
      continue
    }
    if (!inOn) continue
    if (line.trim() === '' || line.trim().startsWith('#')) {
      insertAt = i + 1
      continue
    }
    const indent = line.match(/^(\s*)/)[1].length
    if (indent === 0) {
      insertAt = i
      break
    }
    insertAt = i + 1
  }

  const block = ['', ENV_MARKER, 'env:', ...runnerEnvLines(runners), '']
  const next = lines.slice()
  next.splice(insertAt, 0, ...block)
  return next
}

function fixMalformedEnvBlocks (lines) {
  const next = lines.slice()
  for (let i = 0; i < next.length; i++) {
    if (next[i] !== 'env:') continue
    if (next[i + 1]?.trim() !== ENV_MARKER) continue

    const marker = next.splice(i + 1, 1)[0]
    next.splice(i, 0, marker)
  }
  return next
}

function mergeRunnerEnv (text, runners) {
  let lines = text.split('\n')
  lines = removeExistingRunnerEnv(lines)
  lines = fixMalformedEnvBlocks(lines)

  const existing = findWorkflowLevelEnv(lines)
  if (existing) {
    const hasMarker = lines.slice(existing.start, existing.end).some((line) => line.trim() === ENV_MARKER)
    if (!hasMarker) {
      lines.splice(existing.insertAt, 0, ...runnerEnvInsertLines(runners))
    }
    return lines.join('\n')
  }

  return insertEnvBlock(lines, runners).join('\n')
}

function replaceLiterals (text, runners) {
  const byValue = Object.entries(runners).sort((a, b) => b[1].length - a[1].length)
  let result = text

  for (const [key, value] of byValue) {
    const expr = envExpr(key)

    result = result.replace(
      new RegExp(`^(\\s*runs-on:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${expr}`
    )
    result = result.replace(
      new RegExp(`^(\\s*runner:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${expr}`
    )
    result = result.replace(
      new RegExp(`^(\\s*runner_label:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${expr}`
    )
    result = result.replace(
      new RegExp(`^(\\s*device_label:\\s*)${escapeRegExp(value)}(\\s*)$`, 'gm'),
      `$1${expr}$2`
    )
    result = result.replace(
      new RegExp(`^(\\s*-\\s*os:\\s*)${escapeRegExp(value)}\\s*$`, 'gm'),
      `$1${expr}`
    )
    result = result.replace(
      new RegExp(`(\\bos:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${expr}$2`
    )
    result = result.replace(
      new RegExp(`(\\brunner:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${expr}$2`
    )
    result = result.replace(
      new RegExp(`(\\brunner_label:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${expr}$2`
    )
    result = result.replace(
      new RegExp(`(\\bdevice_label:\\s*)${escapeRegExp(value)}([,}\\s]|$)`, 'g'),
      `$1${expr}$2`
    )
    result = result.replace(
      new RegExp(`matrix\\.os == '${escapeRegExp(value)}'`, 'g'),
      `matrix.os == env.${envName(key)}`
    )
    result = result.replace(
      new RegExp(`matrix\\.os != '${escapeRegExp(value)}'`, 'g'),
      `matrix.os != env.${envName(key)}`
    )
    result = result.replace(
      new RegExp(`matrix\\.runner == '${escapeRegExp(value)}'`, 'g'),
      `matrix.runner == env.${envName(key)}`
    )
    result = result.replace(
      new RegExp(`"\\$\\{\\{ matrix\\.os \\}\\}" = "${escapeRegExp(value)}"`, 'g'),
      `"$\{\{ matrix.os \}\}" = "$\{\{ env.${envName(key)} \}\}"`
    )
  }

  return result
}

function escapeRegExp (value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function patchWorkflow (filePath, runners) {
  const original = fs.readFileSync(filePath, 'utf8')
  let text = mergeRunnerEnv(original, runners)
  text = replaceLiterals(text, runners)
  if (text !== original) {
    fs.writeFileSync(filePath, text.endsWith('\n') ? text : text + '\n')
    return true
  }
  return false
}

function main () {
  const runnersYaml = fs.readFileSync(runnersYamlPath, 'utf8')
  const runners = parseRunnersYaml(runnersYaml)
  if (Object.keys(runners).length === 0) {
    throw new Error(`No runners parsed from ${runnersYamlPath}`)
  }

  writeActionYml(runners)

  const workflowFiles = fs.readdirSync(workflowsDir)
    .filter((name) => name.endsWith('.yml') || name.endsWith('.yaml'))
    .map((name) => path.join(workflowsDir, name))

  let patched = 0
  for (const file of workflowFiles) {
    if (patchWorkflow(file, runners)) patched += 1
  }

  console.log(`Synced ${Object.keys(runners).length} runner labels`)
  console.log(`Updated action: ${path.relative(repoRoot, actionPath)}`)
  console.log(`Patched ${patched}/${workflowFiles.length} workflow files`)
}

main()
